try {
  const first = $('Ops Webhook').first().json || {};
  const b = first.body || first;
  const action = String(b.action || '').toLowerCase();
  const ACTIONS = ["daily","today","urgent","health","stale","followups","replies","radar_new","content_status","content_performance","panel","radar_gate","prep_gate","content_gate","rss_gate","competitor_gate","pieces_gate","igweek_gate","ig_week_status","storyday_gate","story_proposal_save","editorial_plan","radar_report","content_radar_report","job_report","alerts_poll","alerts_ack","ideas_list","ideas_gate","ideas_propose","ideas_revise","taller_list","mail_view","history_list","week_status","results_view","learning_context","learning_propose"];
  if (!ACTIONS.includes(action)) throw new Error('action inválida: usa ' + ACTIONS.join(' | '));
  const dry = b.dry_run === true;
  // la hora solo se puede simular en consultas de lectura o con dry_run (pruebas); las escrituras siempre usan la hora real
  const now = Number.isFinite(Number(b.now_ms)) && (dry || ['daily', 'today', 'urgent', 'health', 'stale', 'followups', 'replies', 'radar_new', 'content_status', 'content_performance', 'panel', 'radar_gate', 'prep_gate', 'content_gate', 'rss_gate', 'competitor_gate', 'pieces_gate', 'igweek_gate', 'ig_week_status', 'storyday_gate', 'story_proposal_save', 'editorial_plan', 'ideas_list', 'ideas_gate', 'taller_list', 'mail_view', 'history_list', 'week_status', 'results_view', 'learning_context', 'learning_propose'].includes(action)) ? Number(b.now_ms) : Date.now();
  const need = {
    sb: !['alerts_ack'].includes(action) || true,
    ghl: ['daily', 'today', 'urgent', 'stale', 'replies', 'panel'].includes(action),
    n8n: ['daily', 'today', 'urgent', 'health', 'alerts_poll', 'panel'].includes(action),
    deep: (action === 'health' && b.deep === true) || (action === 'alerts_poll' && b.deep_gmail === true) || (action === 'daily' && b.deep === true),
    learn: action === 'content_performance',
    panel: action === 'panel',
    growth: ['panel', 'radar_gate', 'prep_gate', 'content_gate', 'rss_gate', 'competitor_gate', 'pieces_gate', 'igweek_gate', 'ig_week_status', 'storyday_gate', 'story_proposal_save', 'editorial_plan', 'content_performance', 'alerts_poll', 'health', 'ideas_list', 'ideas_gate', 'ideas_propose', 'ideas_revise', 'taller_list', 'mail_view', 'history_list', 'week_status', 'results_view', 'learning_context', 'learning_propose'].includes(action),
  };
  const sb = 'https://uwquwjmiofixzugttals.supabase.co/rest/v1/', none = 'https://localhost.invalid/';
  const iso = (ms) => new Date(ms).toISOString();
  const n8n = 'https://n8n.srv1650725.hstgr.cloud/api/v1/';
  const u = {
    messages: sb + 'outreach_messages?created_at=gte.' + iso(now - 45 * 86400000) + '&select=id,candidate_id,company_name,kind,direction,status,classification,subject,body,to_email,content_hash,sent_at,created_at,updated_at,metadata,error,edited_by_christian_at,scheduled_for,approved_at,learning_pair&order=created_at.desc&limit=700',
    cands: sb + 'prospect_candidates?status=in.(in_ghl,accepted,contacted)&select=id,company_name,status,band,priority_score,source_name,created_at,ghl_stage,ghl_opportunity_id,ghl_contact_id,next_action_at,channel_state,industry,location,domain,angle:canonical->>outreach_angle,quote:canonical->evidence_quotes->0->>quote,contact:canonical->contact,sflags:canonical->source_flags,extra_emails:canonical->extra_contacts->emails,more_emails:canonical->emails&order=created_at.desc&limit=400',
    pieces: sb + 'content_pieces?select=id,topic,channel,resource_id,editorial_type:piece->>editorial_type,status,ghl_status,ghl_approval_status,scheduled_at,published_at,is_test,learning,learned_at,created_at,format,category,score,hook:piece->>hook,taller_status,needs_by,updated_at,motion_language:piece->motion_brief->>language,story_template:piece->story->>template&order=created_at.desc&limit=300',
    metrics: sb + 'content_metrics?captured_at=gte.' + iso(now - 30 * 86400000) + '&select=content_piece_id,metric_window,status,likes,comments,shares,captured_at&order=captured_at.desc&limit=200',
    signals: sb + 'content_sources?signal_status=eq.candidate&select=id,title,created_at,signal_type,signal_score,angle:signal->>angle&order=created_at.desc&limit=200',
    review: need.panel ? sb + 'content_pieces?is_test=eq.false&status=in.(in_review,drafted,scored,scheduled,approved)&select=id,status,score,rationale,ghl_post_id,scheduled_at,piece,cta_mode,resource:content_resources(name,url)&order=created_at.desc&limit=10' : none,
    alerts: sb + 'ops_alerts?select=*&order=last_seen_at.desc&limit=200',
    runs: sb + 'ops_runs?select=*&order=created_at.desc&limit=40',
    config: sb + 'outreach_config?id=eq.1&select=mode,paused,send_allowlist,daily_cap,linkedin_mode,linkedin_daily_cap,autosend_enabled,autosend_min_score,autosend_updated_at,tz,window_start,window_end',
    accounts: ['alerts_poll', 'health', 'panel'].includes(action) ? 'https://services.leadconnectorhq.com/social-media-posting/pxHuOsiz2i3lM6BtC9IM/accounts' : none,
    opps: need.ghl ? 'https://services.leadconnectorhq.com/opportunities/search?location_id=pxHuOsiz2i3lM6BtC9IM&pipeline_id=trSWhAcNDyUMmPlYIEib&status=open&limit=100' : none,
    tasks: need.ghl ? 'https://services.leadconnectorhq.com/locations/pxHuOsiz2i3lM6BtC9IM/tasks/search' : none,
    wfs: need.n8n ? n8n + 'workflows?limit=100' : none,
    errors: need.n8n ? n8n + 'executions?status=error&limit=100' : none,
    gmail: need.deep ? 'https://n8n.srv1650725.hstgr.cloud/webhook/' : none,
    learn: need.learn ? 'https://n8n.srv1650725.hstgr.cloud/webhook/atacama-content-learnings' : none,
  };
  const leads_read = action === 'content_performance' ? [{ key: 'leads', url: sb + 'lead_submissions?created_at=gte.' + iso(now - 60 * 86400000) + '&select=source_page,campaign,created_at&order=created_at.desc&limit=400' }] : [];
  const growth_reads = need.growth ? leads_read.concat([
    { key: 'content_cfg', url: sb + 'content_config?id=eq.1&select=*' },
    { key: 'feeds', url: sb + 'content_feeds?select=slug,name,enabled,last_checked_at,last_status,last_error,consecutive_failures&limit=100' },
    { key: 'feed_new', url: sb + 'content_feed_items?status=eq.new&select=relevance&limit=500' },
    { key: 'intel', url: sb + 'content_intel_reports?select=id,created_at,competitors_scanned,report&order=created_at.desc&limit=1' },
    { key: 'resources', url: sb + 'content_resources?select=id,slug,name,type,topic,audience,problem,cta_mode,url,status&limit=100' },
    { key: 'resource_use', url: sb + 'content_pieces?resource_id=not.is.null&is_test=eq.false&select=resource_id&limit=500' },
    { key: 'interviews', url: sb + 'founder_interviews?is_test=eq.false&select=status,question,asked_at&order=asked_at.desc&limit=10' },
    { key: 'story_props', url: sb + 'story_proposals?select=for_date,decision,story_count,items,manual_notes,status,created_at&order=for_date.desc&limit=10' },
    { key: 'sys_state', url: sb + 'system_state?id=eq.1&select=*' },
    { key: 'ideas', url: sb + 'content_ideas?is_test=eq.false&status=in.(proposed,approved,changed)&select=id,title,status,channel,week_start,created_at,is_test&order=created_at.desc&limit=200' },
  ]) : [];
  // v3 · Fase 4 (Ideas): lecturas propias de cada acción
  const P = b.params && typeof b.params === 'object' ? b.params : {};
  const UU = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const day = (ms) => new Date(ms).toISOString().slice(0, 10);
  if (action === 'ideas_list') growth_reads.push({ key: 'ideas_rows', url: sb + 'content_ideas?is_test=eq.false&week_start=gte.' + day(now - 7 * 86400000) + '&select=*&order=created_at.desc&limit=300' }, { key: 'idea_batches', url: sb + 'content_idea_batches?is_test=eq.false&select=*&order=created_at.desc&limit=12' });
  if (['ideas_gate', 'ideas_propose', 'ideas_revise'].includes(action)) growth_reads.push({ key: 'ideas_all', url: sb + 'content_ideas?week_start=gte.' + day(now - 42 * 86400000) + '&select=id,title,hook,status,channel,format,week_start,origin,ficha_complete,change_request,core_message,evidence,source_ids,is_test,history&limit=500' }, { key: 'intel_ids', url: sb + 'content_intel_reports?select=id,created_at&order=created_at.desc&limit=10' });
  // taller_list con params.test=true (solo con la llave interna; /ops nunca lo pide) muestra SOLO las piezas TEST: sirve para verificar en vivo sin datos reales.
  const TT = P.test === true ? 'true' : 'false';
  if (action === 'taller_list') growth_reads.push({ key: 'tpieces', url: sb + 'content_pieces?taller_status=not.is.null&is_test=eq.' + TT + '&select=*&order=updated_at.desc&limit=200' }, { key: 'tversions', url: sb + 'content_versions?is_test=eq.' + TT + '&select=*&order=created_at.desc&limit=400' },
    { key: 'tfeedback', url: sb + 'content_feedback?is_test=eq.' + TT + '&select=*&order=created_at.desc&limit=500' }, { key: 'tideas', url: sb + 'content_ideas?is_test=eq.' + TT + '&piece_id=not.is.null&select=*&limit=300' },
    { key: 'ttaken', url: sb + 'content_pieces?status=in.(scheduled,in_review,approved)&scheduled_at=gte.' + iso(now - 86400000) + '&select=id,channel,format,scheduled_at&limit=300' });
  // v3 · Fase 6: sección Prospección y correo (solo lectura)
  if (action === 'mail_view') growth_reads.push({ key: 'mail_msgs', url: sb + 'outreach_messages?created_at=gte.' + iso(now - 120 * 86400000) + '&select=id,candidate_id,company_name,kind,direction,status,classification,subject,body,to_email,from_email,content_hash,sent_at,created_at,updated_at,approved_at,scheduled_for,metadata,error,edited_by_christian_at&order=created_at.desc&limit=1500' },
    { key: 'mail_supp', url: sb + 'outreach_suppression?select=email,reason,created_at&order=created_at.desc&limit=500' },
    { key: 'mail_cfg', url: sb + 'outreach_config?id=eq.1&select=mode,paused,daily_cap,window_start,window_end,tz,followup_days,legal_footer,autosend_enabled,autosend_min_score,funnel_min_sample,config_updated_by,updated_at' },
    { key: 'mail_cands', url: sb + 'prospect_candidates?select=id,company_name,status,industry,ghl_stage&limit=2000' });
  // v3 · Fase 7: historial legible (90 días) y «Mi semana» (solo lectura)
  if (action === 'panel') growth_reads.push({ key: 'meet_today', url: sb + 'lead_submissions?meeting_start=gte.' + iso(now - 86400000) + '&meeting_start=lte.' + iso(now + 86400000) + '&select=meeting_start,name,company&order=meeting_start.asc&limit=20' });
  if (['results_view', 'ideas_gate'].includes(action)) growth_reads.push(
    { key: 'r_pieces', url: sb + 'content_pieces?created_at=gte.' + iso(now - 120 * 86400000) + '&select=id,topic,channel,format,published_at,scheduled_at,created_at,taller_status,resource_id,is_test,idea:content_ideas!content_pieces_idea_id_fkey(keyword)&order=created_at.desc&limit=400' },
    { key: 'r_att', url: sb + 'content_attributions?created_at=gte.' + iso(now - 90 * 86400000) + '&select=piece_id,resource_id,source,created_at,is_test&limit=2000' },
    { key: 'r_leads', url: sb + 'lead_submissions?source_section=eq.recurso-cierre&created_at=gte.' + iso(now - 90 * 86400000) + '&select=source_page,source_section,created_at,meeting_start&limit=1000' });
  if (action === 'results_view') growth_reads.push(
    { key: 'r_metrics', url: sb + 'content_metrics?captured_at=gte.' + iso(now - 90 * 86400000) + '&select=content_piece_id,metric_window,likes,comments,shares&limit=2000' },
    { key: 'r_versions', url: sb + 'content_versions?created_at=gte.' + iso(now - 90 * 86400000) + '&select=piece_id,version_no,cost_credits,created_at,is_test&limit=2000' },
    { key: 'r_feedback', url: sb + 'content_feedback?created_at=gte.' + iso(now - 90 * 86400000) + '&select=piece_id,created_at,is_test&limit=2000' });
  if (['results_view', 'learning_context', 'learning_propose'].includes(action)) growth_reads.push(
    { key: 'l_events', url: sb + 'learning_events?created_at=gte.' + iso(now - 365 * 86400000) + '&select=id,type,subject_id,before,after,reason,is_test,created_at&order=created_at.desc&limit=3000' },
    { key: 'l_props', url: sb + 'learning_proposals?select=id,target,proposal,evidence,sample_size,status,decided_at,is_test,created_at&order=created_at.desc&limit=200' });
  if (action === 'history_list') growth_reads.push({ key: 'h_audit', url: sb + 'operator_audit_log?created_at=gte.' + iso(now - 90 * 86400000) + '&select=id,actor,tool,status,entity,params,created_at&order=created_at.desc&limit=3000' },
    { key: 'h_runs', url: sb + 'ops_runs?created_at=gte.' + iso(now - 90 * 86400000) + '&select=id,kind,status,summary,created_at&order=created_at.desc&limit=1000' },
    { key: 'h_msgs', url: sb + 'outreach_messages?updated_at=gte.' + iso(now - 90 * 86400000) + '&select=direction,status,classification,error,company_name,sent_at,created_at,updated_at&order=updated_at.desc&limit=3000' },
    { key: 'h_pieces', url: sb + 'content_pieces?published_at=gte.' + iso(now - 90 * 86400000) + '&select=id,topic,published_at,is_test&limit=500' },
    { key: 'h_alerts', url: sb + 'ops_alerts?severity=in.(critical,high)&first_seen_at=gte.' + iso(now - 90 * 86400000) + '&select=alert_key,severity,title,status,first_seen_at,resolved_at,meta&order=first_seen_at.desc&limit=800' });
  if (action === 'week_status') growth_reads.push({ key: 'w_ideas', url: sb + 'content_ideas?week_start=gte.' + day(now - 7 * 86400000) + '&select=week_start,status,is_test&limit=500' },
    { key: 'w_meet', url: sb + 'lead_submissions?meeting_start=gte.' + iso(now - 8 * 86400000) + '&meeting_start=lte.' + iso(now + 8 * 86400000) + '&select=meeting_start,name,company&order=meeting_start.asc&limit=100' },
    { key: 'w_pieces', url: sb + 'content_pieces?taller_status=not.is.null&is_test=eq.false&select=id,topic,taller_status,status,needs_by,credits_spent,is_test&limit=500' });
  if (action === 'ideas_gate') growth_reads.push({ key: 'sources_verified', url: sb + 'content_sources?verified=eq.true&created_at=gte.' + iso(now - 21 * 86400000) + '&select=id,title,url,kind,signal_type,source_date,created_at&order=created_at.desc&limit=60' });
  if (['ideas_propose', 'ideas_revise'].includes(action)) {
    const evs = (action === 'ideas_propose' ? ((P.proposal || {}).ideas || []) : [P.idea || {}]).flatMap((i) => (i && Array.isArray(i.evidence) ? i.evidence : []));
    const ids = (t) => [...new Set(evs.filter((e) => e && e.type === t && UU.test(String(e.id || ''))).map((e) => String(e.id).toLowerCase()))].slice(0, 60);
    const zero = '00000000-0000-0000-0000-000000000000';
    growth_reads.push({ key: 'ev_sources', url: sb + 'content_sources?id=in.(' + (ids('source').concat([zero])).join(',') + ')&select=id,verified' }, { key: 'ev_pieces', url: sb + 'content_pieces?id=in.(' + (ids('metric').concat([zero])).join(',') + ')&select=id,published_at' });
    if (action === 'ideas_revise') growth_reads.push({ key: 'idea_one', url: sb + 'content_ideas?id=eq.' + (UU.test(String(P.idea_id || '')) ? String(P.idea_id).toLowerCase() : zero) + '&select=*&limit=1' });
  }
  return [{ json: { growth_reads, action, params: b.params && typeof b.params === 'object' ? b.params : {}, hermes: b.hermes && typeof b.hermes === 'object' ? b.hermes : null, keys: Array.isArray(b.keys) ? b.keys.map(String).slice(0, 50) : [], report: b.report && typeof b.report === 'object' ? b.report : {}, dry, now, need, u } }];
} catch (e) { return [{ json: { fatal: String((e && e.message) || e) } }]; }

function ageText(ms) {
  const mins = Math.max(0, Math.round(ms / 60000));
  if (mins < 90) return mins + ' min';
  if (mins < 60 * 36) return Math.round(mins / 60) + ' h';
  return Math.round(mins / 1440) + ' días';
}

function alertsText(notify) {
  if (!notify || !notify.length) return '';
  const sev = { critical: 'CRÍTICO', high: 'IMPORTANTE', info: 'AVISO' };
  // Las informativas «solo panel» (v3 §8.5) no van a Telegram: se marcan como avisadas y se ven en /ops.
  const notices = notify.filter((a) => a.meta && a.meta.notice), alerts = notify.filter((a) => !(a.meta && (a.meta.notice || a.meta.panel_only)));
  const blocks = [];
  if (alerts.length) {
    const lines = ['ATACAMA OS · ' + (alerts.length === 1 ? 'alerta' : alerts.length + ' alertas')];
    alerts.forEach((a) => lines.push('• ' + sev[a.severity] + ' · ' + a.title + (a.detail ? ' — ' + a.detail : '') + (a.repeat ? ' (sigue sin resolverse)' : '')));
    blocks.push(lines.join('\n'));
  }
  notices.forEach((a) => blocks.push(a.meta.notice));
  return blocks.join('\n\n');
}

function buildSections(d) {
  const c = summarizeCommercial(d), ct = summarizeContent(d), h = healthReport(d);
  const tz = (d.cfg && d.cfg.tz) || 'America/Santiago';
  const action = [], review = [], good = [];
  const push = (arr, key, text) => arr.push({ key, text });
  // --- NECESITA TU ACCIÓN
  const respNames = c.awaiting_reply.map((r) => r.company);
  if (c.awaiting_reply.length) push(action, 'replies', plural(c.awaiting_reply.length, 'respuesta por atender', 'respuestas por atender') + ': ' + names(respNames, 3) + (c.new_replies.length ? ' (' + plural(c.new_replies.length, 'llegó', 'llegaron') + ' en las últimas 36 h)' : ''));
  else if (c.new_replies.length) push(action, 'replies', plural(c.new_replies.length, 'respuesta nueva', 'respuestas nuevas') + ': ' + names(c.new_replies.map((r) => r.company), 3));
  if (c.followups.overdue.length) push(action, 'fu_overdue', plural(c.followups.overdue.length, 'seguimiento vencido', 'seguimientos vencidos') + ': ' + names(c.followups.overdue.map((f) => f.company + (f.draft ? ' (borrador listo)' : ' (sin borrador)')), 3));
  if (c.followups.today.length) push(action, 'fu_today', plural(c.followups.today.length, 'seguimiento para hoy', 'seguimientos para hoy') + ': ' + names(c.followups.today.map((f) => f.company + (f.draft ? ' (borrador listo)' : '')), 3));
  if (c.no_next_step.length) push(action, 'no_next', plural(c.no_next_step.length, 'oportunidad sin próximo paso', 'oportunidades sin próximo paso') + ': ' + names(c.no_next_step.map((o) => o.company), 3));
  const staleHot = c.stale.filter((s) => ['nuevo', 'respondio', 'propuesta', 'diagnostico'].includes(s.stage));
  if (staleHot.length) push(action, 'stale_hot', plural(staleHot.length, 'oportunidad estancada', 'oportunidades estancadas') + ': ' + names(staleHot.map((s) => s.company + ' (' + s.stage + ', ' + s.days + ' d)'), 3));
  if (ct.pending_review.length) push(action, 'content_pending', plural(ct.pending_review.length, 'publicación pendiente de aprobación', 'publicaciones pendientes de aprobación') + ': ' + names(ct.pending_review, 2));
  if (ct.failed.length || ct.late.length) push(action, 'content_failed', 'Publicación con problema: ' + names(ct.failed.concat(ct.late), 2));
  if (c.outreach.approved_pending) push(action, 'approved_pending', plural(c.outreach.approved_pending, 'correo aprobado esperando salir', 'correos aprobados esperando salir') + (c.outreach.mode === 'off' ? ' (el envío está apagado)' : ''));
  const sysBad = h.components.filter((x) => x.status !== 'ok');
  sysBad.filter((x) => x.status === 'fallo').forEach((x) => push(action, 'sys_' + x.name, 'FALLO · ' + x.name + ': ' + x.reason));
  if (c.overdue_tasks_total) {
    const imp = c.task_groups.filter((g) => /respuesta|reuni|propuesta|diagn/i.test(g.type));
    if (imp.length) push(action, 'tasks_important', 'Tareas vencidas importantes: ' + imp.map((g) => g.count + ' «' + g.type + '»').join(', '));
  }
  missingNotes(d).forEach((m, i) => push(action, 'missing' + i, m));
  // --- PARA REVISAR
  const p = c.prospects;
  if (p.new_24h || p.backlog) {
    const bits = [];
    if (p.new_24h) bits.push(plural(p.new_24h, 'candidato nuevo', 'candidatos nuevos') + (p.new_alta ? ' (' + p.new_alta + ' prioridad alta)' : '') + (p.radar_new.length ? ' · del Radar: ' + names(p.radar_new.map((r) => r.company), 3) : ''));
    if (p.backlog) bits.push(plural(p.backlog, 'prospecto en Investigado', 'prospectos en Investigado') + ' sin decisión' + (p.backlog_oldest_days ? ' (el más antiguo: ' + p.backlog_oldest_days + ' d)' : '') + (p.backlog_alta ? ', ' + p.backlog_alta + ' de prioridad alta' : ''));
    push(review, 'prospects', 'Prospección: ' + bits.join(' · '));
  }
  if (c.followups.drafts.length && !c.followups.overdue.length && !c.followups.today.length) push(review, 'fu_drafts', plural(c.followups.drafts.length, 'borrador de seguimiento esperando tu aprobación', 'borradores de seguimiento esperando tu aprobación') + ': ' + names(c.followups.drafts.map((f) => f.company), 3));
  const staleOther = c.stale.filter((s) => !['nuevo', 'respondio', 'propuesta', 'diagnostico'].includes(s.stage));
  if (staleOther.length) push(review, 'stale_other', plural(staleOther.length, 'oportunidad quieta', 'oportunidades quietas') + ': ' + names(staleOther.map((s) => s.company + ' (' + s.stage + ', ' + s.days + ' d)'), 3));
  if (c.task_groups.length) push(review, 'tasks', plural(c.overdue_tasks_total, 'tarea vencida', 'tareas vencidas') + ': ' + c.task_groups.slice(0, 3).map((g) => g.count + ' «' + g.type + '»').join(', '));
  if (ct.scheduled.length) push(review, 'content_sched', 'Programadas: ' + ct.scheduled.slice(0, 3).map((s) => s.label + ' ' + fmtDateTime(Date.parse(s.at), tz)).join(' · '));
  if (ct.published_recent.length) push(review, 'content_pub', 'Publicadas (72 h): ' + names(ct.published_recent.map((x) => x.label), 2));
