  const storyOpen = [];
  days.forEach((k) => storySlots.forEach((s) => { const ms = igZoned(k, s, tz); if (ms >= now + 3 * 3600000 && !takenSlots[k + '|' + s]) storyOpen.push({ date: k, slot: s, iso: new Date(ms).toISOString() }); }));
