  (v.items || []).forEach((it) => lines.push((it.hour ? it.hour + ' · ' : '') + ({ REPOST_FEED: 'Repost', SUPPORT_STORY: 'Apoyo', ORIGINAL_STORY: 'Original' }[it.kind] || it.kind) + ': ' + (it.copy || it.objective)));
