  const times = piece.channel === 'instagram' ? (piece.format === 'historia' ? stories : [feedAt]) : ['10:00'];
  const isFeed = (p) => p.channel === 'instagram' && p.format !== 'historia';
  const list = (Array.isArray(taken) ? taken : []).filter((p) => p && p.scheduled_at && p.id !== piece.id);
  const start = weekStart && /^\d{4}-\d{2}-\d{2}$/.test(weekStart) ? weekStart : new Date(nowMs).toISOString().slice(0, 10);
  for (let k = 0; k < 21; k++) {
    const day = new Date(start + 'T12:00:00Z'); day.setUTCDate(day.getUTCDate() + k);
    const ds = day.toISOString().slice(0, 10);
    const sameDay = list.filter((p) => new Date(Date.parse(p.scheduled_at) + off * 3600000).toISOString().slice(0, 10) === ds);
    if (piece.channel === 'instagram' && piece.format !== 'historia' && sameDay.some(isFeed)) continue;
    if (piece.channel !== 'instagram' && sameDay.some((p) => p.channel === piece.channel)) continue;
    if (piece.format === 'historia' && sameDay.filter((p) => p.channel === 'instagram' && p.format === 'historia').length >= 3) continue;
    for (const t of times) {
      const [hh, mm] = t.split(':').map(Number);
      const iso = new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate(), hh - off, mm || 0)).toISOString();
      if (Date.parse(iso) < nowMs + 60 * 60000) continue;
      if (sameDay.some((p) => Date.parse(p.scheduled_at) === Date.parse(iso))) continue;
      return iso;
    }
  }
  return null;
}

function tallerScheduleFinal(x) {
  const p = x.piece, pre = x.pre, post = x.post, now = Number(x.now) || Date.now();
  const nowIso = new Date(now).toISOString();
  if (!post || !post._id) return { error: 'ghl_no_confirmo', message: 'GHL no confirmó la creación del post. No lo doy por programado: revisa GHL.' };
  const st = String(post.status || '').toLowerCase(), ap = ((post.postApprovalDetails || {}).approvalStatus) || null;
  const okDirect = pre.direct && st === 'scheduled' && ap === 'approved';
  const okClick = !pre.direct && st === 'in_review';
  if (!okDirect && !okClick) return { error: 'ghl_estado_inesperado', message: 'GHL creó el post pero quedó «' + st + '/' + (ap || '—') + '». Revísalo en GHL; no lo doy por programado.', ghl_post_id: post._id };
  const ts = okDirect ? 'programada' : 'programada_pendiente_de_clic';
  const by = 'Christian vía /ops Taller';
  const ghlMedia = (Array.isArray(x.media) ? x.media : []).map((m) => ({ url: m.url, fileId: m.fileId || null }));
  const writes = [{ method: 'PATCH', path: 'content_pieces?id=eq.' + p.id + '&taller_status=eq.' + p.taller_status, body: { piece: { ...(p.piece || {}), ghl_media: ghlMedia }, taller_status: ts, status: okDirect ? 'scheduled' : 'in_review', ghl_post_id: post._id, ghl_account_id: pre.account, ghl_status: st, ghl_approval_status: ap, scheduled_at: pre.schedule_iso, approved_at: okDirect ? nowIso : null, updated_at: nowIso }, prefer: 'return=representation', check_rows: true, check_message: 'El post se creó en GHL (' + post._id + ') pero la pieza cambió mientras tanto: revisa el Taller.' }];
  if (p.idea_id) writes.push({ method: 'PATCH', path: 'content_ideas?id=eq.' + p.idea_id + '&status=in.(in_production,approved)', body: { status: 'scheduled', updated_at: nowIso }, prefer: 'return=minimal' });
  if (Number(p.current_version) === 1 && !x.had_feedback) writes.push({ method: 'POST', path: 'learning_events', body: { type: 'piece_ok', subject_id: p.id, before: { format: p.format, channel: p.channel, lane: p.lane }, after: { version: 1 }, reason: 'programada sin cambios (v1)', by, is_test: Boolean(p.is_test), created_at: nowIso }, prefer: 'return=minimal' });
  const when = new Date(Date.parse(pre.schedule_iso) - 3 * 3600000).toISOString().slice(0, 16).replace('T', ' ');
  return { resp: { ok: true, status: ts, ghl_post_id: post._id, schedule_date: pre.schedule_iso, needs_ghl: !okDirect, message: okDirect ? 'Programada en GHL para el ' + when + ' (hora de Chile). Tu clic fue la aprobación.' : 'Carrusel creado en GHL para el ' + when + ' (hora de Chile), EN REVISIÓN: ábrelo en GHL, comprueba las ' + (pre.paths.length) + ' láminas y dale el último clic de aprobar.' }, writes };
}

function tallerSchedulePrecheck(x) {
  const p = x.piece, v = x.version, now = Number(x.now) || Date.now();
  if (!p || !p.taller_status) return { error: 'pieza_no_encontrada', message: 'No encontré esa pieza en el Taller.' };
  if (!['para_revisar', 'lista'].includes(p.taller_status)) return { error: 'estado_invalido', message: 'Solo se programa una pieza «para revisar» o «lista» (estado: ' + p.taller_status + ').' };
  if (p.ghl_post_id && ['programada', 'programada_pendiente_de_clic'].includes(p.taller_status)) return { error: 'ya_programada', message: 'Esa pieza ya está en GHL.' };
  if (!v) return { error: 'sin_version', message: 'Esa pieza todavía no tiene una versión para programar.' };
  const account = tallerAccount(p.channel);
  if (!account) return { error: 'red_invalida', message: 'Red sin cuenta conectada en GHL.' };
  const at = Date.parse(String(x.schedule_at || ''));
  if (!Number.isFinite(at)) return { error: 'falta_fecha', message: 'Elige fecha y hora.' };
  if (at < now + 30 * 60000) return { error: 'fecha_pasada', message: 'La fecha debe ser al menos 30 minutos en el futuro.' };
  if (at > now + 55 * 86400000) return { error: 'fecha_lejana', message: 'Máximo 55 días hacia adelante (las conexiones de GHL vencen el 11/12-dic).' };
  const errs = tallerValidateAssets(v.assets, p);
  if (errs.length) return { error: 'archivos_invalidos', message: errs.join(' · ') };
  const caption = String(v.caption || '').trim();
  if (p.format === 'historia' && caption) return { error: 'historia_sin_texto', message: 'Las historias no llevan texto en GHL: quita el texto antes de programar.' };
  if (p.format !== 'historia' && !caption && p.format !== 'reel') return { error: 'sin_texto', message: 'Falta el texto de la publicación.' };
  const kw = String((x.idea && x.idea.keyword) || (p.piece && p.piece.keyword) || '').trim();
  if (kw && p.format !== 'historia' && !caption.toUpperCase().includes(kw.toUpperCase())) return { error: 'falta_palabra_clave', message: 'La idea lleva la palabra clave «' + kw + '» y el texto no la menciona.' };
  if (p.channel === 'instagram' && caption.length > 2200) return { error: 'texto_largo', message: 'Instagram admite hasta 2.200 caracteres.' };
  if (p.channel !== 'instagram' && caption.length > 3000) return { error: 'texto_largo', message: 'LinkedIn admite hasta 3.000 caracteres.' };
  const off = -3;
  const ds = new Date(at + off * 3600000).toISOString().slice(0, 10);
  const same = (Array.isArray(x.taken) ? x.taken : []).filter((q) => q.id !== p.id && q.scheduled_at && new Date(Date.parse(q.scheduled_at) + off * 3600000).toISOString().slice(0, 10) === ds);
  if (p.channel === 'instagram' && p.format !== 'historia' && same.some((q) => q.channel === 'instagram' && q.format !== 'historia')) return { error: 'hueco_ocupado', message: 'Ya hay una publicación de feed de Instagram ese día. Elige otro día.' };
  if (p.channel !== 'instagram' && same.some((q) => q.channel === p.channel)) return { error: 'hueco_ocupado', message: 'Ya hay una publicación en esa cuenta de LinkedIn ese día.' };
  if (p.format === 'historia' && same.filter((q) => q.channel === 'instagram' && q.format === 'historia').length >= 3) return { error: 'hueco_ocupado', message: 'Ese día ya tiene 3 historias.' };
  const carousel = p.format === 'carrusel';
  const direct = !carousel || Boolean(x.cfg && x.cfg.taller_carousel_direct_schedule === true);
  const paths = (v.assets || []).map((a) => a.path);
  return { ok: true, carousel, direct, needsUpload: paths.length > 0, paths, account, type: tallerGhlType(p.format), caption: p.format === 'historia' ? '' : caption, schedule_iso: new Date(at).toISOString() };
}

function tallerSyncStatus(piece, mapped) {
  const cur = piece && piece.taller_status;
  if (!cur || !['programada', 'programada_pendiente_de_clic'].includes(cur)) return null;
  if (mapped.status === 'published') return 'publicada';
  if (mapped.status === 'discarded') return 'descartada';
  if (mapped.status === 'scheduled' && cur === 'programada_pendiente_de_clic') return 'programada';
  if (mapped.status === 'approved' && cur === 'programada_pendiente_de_clic') return 'programada';
  return null;
}

function tallerTransitions() {
  return {
    en_cola: ['en_produccion', 'en_pc_con_claude', 'para_revisar', 'descartada'],
    en_produccion: ['para_revisar', 'necesita_ayuda', 'descartada'],
    en_pc_con_claude: ['para_revisar', 'descartada'],
    para_revisar: ['cambios_pedidos', 'lista', 'programada', 'programada_pendiente_de_clic', 'descartada'],
    cambios_pedidos: ['en_produccion', 'en_pc_con_claude', 'para_revisar', 'descartada'],
    lista: ['cambios_pedidos', 'programada', 'programada_pendiente_de_clic', 'descartada'],
    programada_pendiente_de_clic: ['programada', 'publicada', 'descartada'],
    programada: ['publicada', 'descartada'],
    necesita_ayuda: ['en_produccion', 'en_pc_con_claude', 'para_revisar', 'descartada'],
    publicada: [],
    descartada: [],
  };
}

function tallerValidateAssets(assets, piece) {
  const a = Array.isArray(assets) ? assets : [];
  const errors = [];
  const re = /^[0-9a-f-]{36}\/v\d{1,3}\/[A-Za-z0-9._-]{1,80}$/;
  a.forEach((x, i) => { if (!x || !re.test(String(x.path || '')) || !String(x.path).startsWith(piece.id + '/')) errors.push('archivo ' + (i + 1) + ': ruta inválida'); });
  const kinds = a.map((x) => (x && /\.mp4$/i.test(String(x.path)) ? 'video' : 'image'));
  const f = piece.format;
  if (f === 'carrusel' && (a.length < 2 || a.length > 10 || kinds.some((k) => k !== 'image'))) errors.push('un carrusel lleva de 2 a 10 imágenes');
  if (f === 'reel' && (a.length !== 1 || kinds[0] !== 'video')) errors.push('un reel lleva un solo video MP4');
  if ((f === 'imagen' || f === 'historia') && (a.length !== 1 || kinds[0] !== 'image')) errors.push('una ' + f + ' lleva una sola imagen');
  if (f === 'texto' && a.length > 1) errors.push('un post de texto lleva como mucho una imagen');
  if (f === 'carrusel' || f === 'imagen') a.forEach((x, i) => { if (x && x.w && x.h && Math.abs(x.w / x.h - 0.8) > 0.02 && piece.channel === 'instagram') errors.push('lámina ' + (i + 1) + ': debe ser 4:5 (1080×1350)'); });
  return errors;
}

function mailView(d) {
  const now = d.now, tz = (d.cfg && d.cfg.tz) || d.tz || 'America/Santiago';
  const cfg = d.cfg || {};
  const msgs = Array.isArray(d.msgs) ? d.msgs : [];
  const cands = Array.isArray(d.cands) ? d.cands : [];
  const supp = Array.isArray(d.supp) ? d.supp : [];
  const today = mvDay(now, tz);
  const out = msgs.filter((m) => m.direction === 'outbound');
  const inb = msgs.filter((m) => m.direction === 'inbound');
  const cap = Number(cfg.daily_cap) || 0;
  const ws = mvHm(cfg.window_start, 540), we = mvHm(cfg.window_end, 1050);
  const clk = mvClock(now, tz);
  const bizDay = clk.wd !== 0 && clk.wd !== 6;
  const inWindow = bizDay && clk.min >= ws && clk.min < we;
  const sentToday = out.filter((m) => m.status === 'sent' && m.sent_at && mvDay(Date.parse(m.sent_at), tz) === today).length;
  const paused = cfg.paused === true || Boolean(d.pause && d.pause.paused);
  const fdays = Array.isArray(cfg.followup_days) && cfg.followup_days.length === 2 ? cfg.followup_days.map(Number) : [3, 7];

  // ---- Cola: aprobados en orden de salida y estimación por día con el tope
  const approved = out.filter((m) => m.status === 'approved' || m.status === 'sending').sort((a, b) => String(a.scheduled_for || a.approved_at || '').localeCompare(String(b.scheduled_for || b.approved_at || '')));
  const leftToday = paused || !bizDay || clk.min >= we ? 0 : Math.max(0, cap - sentToday);
  let day = leftToday > 0 ? 0 : 1, used = 0;
  const queue = approved.map((m) => {
    if (paused) return { m, when: 'en pausa' };
    if (cap <= 0) return { m, when: 'sin tope configurado' };
    if (used >= (day === 0 ? leftToday : cap)) { day++; used = 0; }
    used++;
    return { m, when: day === 0 ? 'hoy' : day === 1 ? 'próximo día hábil' : 'en ' + day + ' días hábiles' };
  }).map((x, i) => ({ id: x.m.id, candidate_id: x.m.candidate_id, company: x.m.company_name || '—', kind: x.m.kind, to: x.m.to_email, subject: x.m.subject, status: x.m.status, approved_at: x.m.approved_at || null, scheduled_for: x.m.scheduled_for || null, position: i + 1, eta: x.when }));
  const willToday = paused ? 0 : Math.min(leftToday, approved.length);
  const willNext = paused ? 0 : Math.min(cap, Math.max(0, approved.length - willToday));

  // ---- Próximo envío
  let next = null;
  if (paused) next = 'en pausa';
  else if (!approved.length) next = 'sin correos aprobados en cola';
  else if (inWindow && sentToday < cap) next = 'en la próxima corrida (cada 10 min)';
  else next = 'próxima ventana hábil a las ' + (cfg.window_start || '09:00');

  // ---- Enviados y respuestas
  const byCand = {};
  inb.forEach((m) => { (byCand[m.candidate_id] = byCand[m.candidate_id] || []).push(m); });
  const replies = inb.filter((m) => m.classification !== 'own').sort((a, b) => String(b.created_at).localeCompare(String(a.created_at))).slice(0, 60)
    .map((m) => ({ id: m.id, candidate_id: m.candidate_id, company: m.company_name || '—', from: m.from_email || null, subject: m.subject || '', snippet: String(m.body || '').slice(0, 280), cls: m.classification || 'other', cls_label: mvClassLabel(m.classification), at: m.created_at,
      reply_draft: out.some((o) => o.candidate_id === m.candidate_id && o.kind === 'reply' && ['draft', 'approved'].includes(o.status)) }));
  const sent = out.filter((m) => m.status === 'sent').sort((a, b) => String(b.sent_at).localeCompare(String(a.sent_at))).slice(0, 60)
    .map((m) => { const r = (byCand[m.candidate_id] || []).filter((x) => x.classification !== 'own' && Date.parse(x.created_at) >= Date.parse(m.sent_at)); return { id: m.id, candidate_id: m.candidate_id, company: m.company_name || '—', kind: m.kind, to: m.to_email, subject: m.subject, sent_at: m.sent_at, answer: r.length ? mvClassLabel(r[0].classification) : null }; });

  // ---- Seguimientos (+N/+M hábiles; nunca se envían solos)
  const fuDrafts = out.filter((m) => ['followup_1', 'followup_2'].includes(m.kind) && ['draft', 'approved'].includes(m.status))
    .map((m) => ({ id: m.id, candidate_id: m.candidate_id, company: m.company_name || '—', kind: m.kind, label: m.kind === 'followup_1' ? 'Seguimiento 1' : 'Seguimiento 2', status: m.status, subject: m.subject, hash: m.content_hash || null, due: null }));
  const upcoming = [];
  out.filter((m) => m.kind === 'initial' && m.status === 'sent' && m.sent_at).forEach((m) => {
    const theirs = (byCand[m.candidate_id] || []).filter((x) => ['reply', 'decline', 'unsubscribe', 'bounce'].includes(x.classification));
    if (theirs.length) return;
    const mine = out.filter((x) => x.candidate_id === m.candidate_id && ['followup_1', 'followup_2'].includes(x.kind));
    const has1 = mine.some((x) => x.kind === 'followup_1'), has2 = mine.some((x) => x.kind === 'followup_2');
    if (has1 && has2) return;
    const n = has1 ? 2 : 1;
    if (has1 && !mine.some((x) => x.kind === 'followup_1' && x.status === 'sent')) return;
    const due = mvAddBiz(Date.parse(m.sent_at), fdays[n - 1], tz);
    upcoming.push({ candidate_id: m.candidate_id, company: m.company_name || '—', n, label: 'Seguimiento ' + n, due: mvDay(due, tz), overdue: due < now });
  });
  upcoming.sort((a, b) => a.due.localeCompare(b.due));

  // ---- Embudo (desglose solo con muestra suficiente)
  const minSample = Number(cfg.funnel_min_sample) || 20;
  const stageOf = (c) => {
    const st = String(c.ghl_stage || '').toLowerCase();
    const mine = out.filter((m) => m.candidate_id === c.id);
    const theirs = (byCand[c.id] || []).filter((x) => ['reply', 'decline'].includes(x.classification));
    if (/ganad|cliente|won/.test(st)) return 6;
    if (/reuni|meeting/.test(st)) return 5;
    if (theirs.length || /respond/.test(st)) return 4;
    if (mine.some((m) => m.kind === 'initial' && m.status === 'sent')) return 3;
    if (mine.some((m) => m.kind === 'initial' && ['approved', 'sending'].includes(m.status))) return 2;
    if (mine.some((m) => m.kind === 'initial' && m.status === 'draft')) return 1;
    return 0;
  };
  const STAGES = ['Investigado', 'Preparado', 'Aprobado', 'Enviado', 'Respondió', 'Reunión', 'Cliente'];
  const reach = STAGES.map(() => 0);
  const byInd = {};
  cands.filter((c) => c.status !== 'discarded').forEach((c) => {
    const s = stageOf(c);
    for (let i = 0; i <= s; i++) reach[i]++;
    if (s >= 3) { const k = String(c.industry || 'Sin rubro'); const b = (byInd[k] = byInd[k] || { sent: 0, replied: 0 }); b.sent++; if (s >= 4) b.replied++; }
  });
  const byAngle = {};
  out.filter((m) => m.kind === 'initial' && m.status === 'sent').forEach((m) => {
    const k = String((m.metadata && m.metadata.cold && m.metadata.cold.angle) || 'Sin ángulo registrado').slice(0, 60);
    const b = (byAngle[k] = byAngle[k] || { sent: 0, replied: 0 }); b.sent++;
    if ((byCand[m.candidate_id] || []).some((x) => ['reply', 'decline'].includes(x.classification))) b.replied++;
  });
  const breakdown = (o) => Object.keys(o).map((k) => ({ key: k, sent: o[k].sent, replied: o[k].replied, rate_pct: o[k].sent >= minSample ? Math.round((o[k].replied / o[k].sent) * 1000) / 10 : null, enough: o[k].sent >= minSample })).sort((a, b) => b.sent - a.sent);

  // ---- Salud
  const health = mvHealth(msgs, cap, now);
  const pace = [];
  for (let i = 0, t = now; pace.length < 7 && i < 14; i++, t -= 86400000) {
    const wd = mvClock(t, tz).wd;
    if (wd === 0 || wd === 6) continue;
    const dk = mvDay(t, tz);
    pace.push({ day: dk, sent: out.filter((m) => m.status === 'sent' && m.sent_at && mvDay(Date.parse(m.sent_at), tz) === dk).length, cap });
  }
  const lastSent = out.filter((m) => m.status === 'sent' && m.sent_at).sort((a, b) => String(b.sent_at).localeCompare(String(a.sent_at)))[0];

  return {
    generated_at: new Date(now).toISOString(),
    hoy: { mode: cfg.mode || 'off', paused, cap, sent_today: sentToday, window: { start: cfg.window_start || '09:00', end: cfg.window_end || '17:30' }, in_window: inWindow, next_send: next, followup_days: fdays,
      autosend: { enabled: cfg.autosend_enabled === true, min_score: Number(cfg.autosend_min_score) || 80 }, legal_footer: cfg.legal_footer || null, funnel_min_sample: minSample,
      drafts: out.filter((m) => m.status === 'draft').length, approved: approved.length, will_today: willToday, will_next: willNext, updated_by: cfg.config_updated_by || null, updated_at: cfg.updated_at || null },
    cola: queue,
    respuestas: { replies, sent },
    seguimientos: { drafts: fuDrafts, upcoming: upcoming.slice(0, 60) },
    embudo: { stages: STAGES.map((s, i) => ({ stage: s, count: reach[i] })), min_sample: minSample, by_industry: breakdown(byInd), by_angle: breakdown(byAngle) },
    salud: { ...health, suppression_total: supp.length, suppression: supp.slice(0, 80).map((s) => ({ email: s.email, reason: s.reason || null, at: s.created_at || null })), pace, last_sent_at: lastSent ? lastSent.sent_at : null },
  };
}

function mvAddBiz(ms, n, tz) {
  let t = ms, left = n;
  while (left > 0) { t += 86400000; const wd = mvClock(t, tz).wd; if (wd !== 0 && wd !== 6) left--; }
  return t;
}

function mvClassLabel(c) {
  return { reply: 'Respuesta', decline: 'Respuesta negativa', bounce: 'Rebote', unsubscribe: 'Baja', auto_reply: 'Fuera de oficina / automática', own: 'Mensaje propio' }[c] || 'Otro';
}

function mvClock(ms, tz) {
  const p = {};
  new Intl.DateTimeFormat('en-US', { timeZone: tz || 'America/Santiago', hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit' }).formatToParts(new Date(ms)).forEach((x) => { p[x.type] = x.value; });
  const wd = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(p.weekday);
  return { min: (Number(p.hour) % 24) * 60 + Number(p.minute), wd };
}

function mvDay(ms, tz) {
  return new Date(ms).toLocaleDateString('en-CA', { timeZone: tz || 'America/Santiago' });
}

function mvHealth(msgs, cap, nowMs) {
  const since = nowMs - 7 * 86400000;
  const L = Array.isArray(msgs) ? msgs : [];
  const sent7 = L.filter((m) => m.direction === 'outbound' && m.status === 'sent' && m.sent_at && Date.parse(m.sent_at) >= since).length;
  const bounces7 = L.filter((m) => m.direction === 'inbound' && m.classification === 'bounce' && Date.parse(m.created_at) >= since).length;
  const unsubs7 = L.filter((m) => m.direction === 'inbound' && m.classification === 'unsubscribe' && Date.parse(m.created_at) >= since).length;
  const complaints7 = L.filter((m) => m.direction === 'inbound' && m.classification === 'unsubscribe' && /spam/i.test(String(m.body || '') + ' ' + String(m.subject || '')) && Date.parse(m.created_at) >= since).length;
  const rate = sent7 ? bounces7 / sent7 : 0;
  const pct = Math.round(rate * 1000) / 10;
  let level = 'ok', alert = null;
  if (sent7 >= 20 && rate >= 0.05) { level = 'critical'; alert = 'Rebote de ' + pct + ' % en 7 días (' + bounces7 + ' de ' + sent7 + '): baja el tope y revisa la lista antes de seguir.'; }
  else if (sent7 > 0 && rate >= 0.03) { level = 'high'; alert = 'Rebote de ' + pct + ' % en 7 días (' + bounces7 + ' de ' + sent7 + '): vigila la calidad de los correos encontrados.'; }
  const c = Number(cap) || 0;
  let suggestion = null;
  if (sent7 >= 50 && rate < 0.02 && complaints7 === 0 && c > 0 && c < 50) suggestion = { from: c, to: Math.min(50, c + 10), text: 'Puedes subir el tope de ' + c + ' a ' + Math.min(50, c + 10) + ': ' + sent7 + ' envíos en 7 días, rebote ' + pct + ' %, sin reclamos. Solo es una sugerencia: el sistema no lo cambia.' };
  else suggestion = { from: c, to: null, text: sent7 < 50 ? 'Aún no conviene subir el tope: hacen falta al menos 50 envíos en 7 días para juzgar (van ' + sent7 + ').' : rate >= 0.02 ? 'No subas el tope: el rebote (' + pct + ' %) está sobre 2 %.' : complaints7 ? 'No subas el tope: hubo ' + complaints7 + ' reclamo(s) esta semana.' : 'El tope ya está en el máximo (50).' };
  return { sent7, bounces7, unsubs7, complaints7, rate_pct: pct, level, alert, suggestion };
}

function mvHm(s, def) {
  const m = String(s || '').match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : def;
}

function hrRules(d) {
  const now = d.now;
  const out = [];
  const add = (key, severity, title, detail, panelOnly) => out.push({ key, severity, title, detail, meta: panelOnly ? { panel_only: true } : {} });
  const DAY = 86400000;

  // 1) Cuentas de redes en GHL: desconectada → crítica; vence en < 14 días → informativa, < 7 → importante, ≤ 3 → crítica
  for (const a of Array.isArray(d.ghl_accounts) ? d.ghl_accounts : []) {
    if (!a || a.deleted) continue;
    const name = (a.platform === 'instagram' ? 'Instagram' : a.platform === 'linkedin' ? 'LinkedIn' : String(a.platform || 'Red')) + ' «' + String(a.name || '') + '»';
    if (a.isExpired === true || a.active === false) { add('ghl_account:' + a.id, 'critical', 'Cuenta desconectada en GHL: ' + name, 'GHL no puede publicar en esta cuenta. Reconéctala en GHL → Marketing → Social Planner → cuentas.', false); continue; }
    const exp = Date.parse(a.expire || '');
    if (!Number.isFinite(exp)) continue;
    const left = Math.ceil((exp - now) / DAY);
    if (left > 14) continue;
    const sev = left <= 3 ? 'critical' : left < 7 ? 'high' : 'info';
    add('ghl_expiry:' + a.id + ':' + sev, sev, 'La conexión de ' + name + ' vence en ' + Math.max(0, left) + (left === 1 ? ' día' : ' días'), 'Reconéctala en GHL antes del ' + new Date(exp).toISOString().slice(0, 10) + ' para que no se caigan las publicaciones programadas.', sev === 'info');
  }

  // 2) Higgsfield: saldo bajo la reserva (300) y gasto semanal de Atacama OS (> 150 importante, > 200 crítica)
  const hg = d.hermes && d.hermes.higgs;
  if (hg && typeof hg === 'object') {
    const reserve = Number(hg.reserve) || 300;
    if (hg.balance != null && Number(hg.balance) < reserve) add('higgs_reserve', 'high', 'Créditos de Higgsfield bajo la reserva', 'Quedan ' + hg.balance + ' créditos (reserva ' + reserve + '). Atacama OS ya no genera imágenes hasta que recargues.', false);
    const sp = Number(hg.spent_week) || 0;
    if (sp > 200) add('higgs_week:critical:' + (hg.week || ''), 'critical', 'Gasto semanal de Higgsfield sobre 200', 'Atacama OS lleva ' + sp + ' créditos esta semana.', false);
    else if (sp > 150) add('higgs_week:high:' + (hg.week || ''), 'high', 'Gasto semanal de Higgsfield sobre 150', 'Atacama OS lleva ' + sp + ' de 200 créditos esta semana.', false);
  }

  // 3) Correo: tope alcanzado con aprobados esperando (informativa: saldrán el próximo día hábil)
  const cfg = d.outreach || {};
  const tz = cfg.tz || 'America/Santiago';
  const dayOf = (ms) => new Date(ms).toLocaleDateString('en-CA', { timeZone: tz });
  const msgs = Array.isArray(d.messages) ? d.messages : [];
  const today = dayOf(now);
  const sentToday = msgs.filter((m) => m.direction === 'outbound' && m.status === 'sent' && m.sent_at && dayOf(Date.parse(m.sent_at)) === today).length;
  const approved = msgs.filter((m) => m.direction === 'outbound' && m.status === 'approved').length;
  const cap = Number(cfg.daily_cap) || 0;
  if (cap > 0 && sentToday >= cap && approved > 0) add('mail_cap:' + today, 'info', 'Tope diario alcanzado con ' + approved + ' aprobados esperando', 'Salen el próximo día hábil. Si quieres más ritmo, sube el tope de a poco (Prospección y correo → Hoy).', true);

  // 4) Taller: piezas que no alcanzan su plazo (viernes de cierre pasado y aún sin programar)
  for (const p of Array.isArray(d.pieces) ? d.pieces : []) {
    if (!p || p.is_test || !p.taller_status || !p.needs_by) continue;
    if (['programada', 'programada_pendiente_de_clic', 'publicada', 'descartada'].includes(p.taller_status)) continue;
    if (Date.parse(p.needs_by) < now) add('taller_late:' + p.id, 'high', 'Pieza del Taller atrasada: ' + String(p.topic || '').slice(0, 60), 'Su cierre era el ' + String(p.needs_by).slice(0, 10) + ' y sigue en «' + p.taller_status + '». Decide en Redes → Taller.', false);
  }

  // 5) Jobs de Hermes que debían correr y no corrieron (no pausados)
  for (const j of (d.hermes && Array.isArray(d.hermes.jobs) ? d.hermes.jobs : [])) {
    if (!j || j.state === 'paused' || j.enabled === false || !j.next_run_at) continue;
    if (!/(atacama|radar)/i.test(String(j.name || ''))) continue;
    const late = now - Date.parse(j.next_run_at);
    if (late > 3 * 3600000) add('hermes_late:' + j.id, 'high', 'Job de Hermes sin correr: ' + j.name, 'Tenía que correr hace ' + Math.round(late / 3600000) + ' h y no lo hizo. Revisa que el gateway de Hermes esté arriba.', false);
  }
  return out;
}

function hiActor(a) {
  const s = String(a || '').toLowerCase();
  if (/v[ií]a hermes|^hermes/.test(s)) return 'Hermes';
  if (/christian/.test(s)) return 'Christian';
  if (/claude/.test(s)) return 'Claude';
  if (/motor|n8n|sistema|atacama os|gmail-sync/.test(s)) return 'Motor';
  return a ? String(a).slice(0, 40) : 'Sistema';
}

function hiAudit(r) {
  const tool = String(r.tool || '').replace(/^ops_/, '');
  const p = r.params || {};
  const e = r.entity || {};
  const actor = hiActor(r.actor);
  const st = String(r.status || '');
  const co = e.company || e.title || e.topic || '';
  const T = (key, section, one, many, href) => ({ key: key + ':' + actor, actor, section, one, many, href: href || null, who: co });
  if (tool === 'save_draft') return st === 'low_quality' ? T('draft_low', 'correo', 'intentó guardar 1 borrador con score bajo (no se guardó)', (n) => 'intentó guardar ' + n + ' borradores con score bajo (no se guardaron)', '/ops?view=aprobaciones&filter=correos')
    : T('draft', 'correo', 'guardó 1 borrador', (n) => 'guardó ' + n + ' borradores', '/ops?view=aprobaciones&filter=correos');
  if (tool === 'email_approve') return T('approve_mail', 'correo', 'aprobó 1 correo', (n) => 'aprobó ' + n + ' correos', '/ops?view=cola');
  if (tool === 'email_save') return p.decision === 'paste' ? T('paste', 'correo', 'pegó su versión en 1 correo', (n) => 'pegó su versión en ' + n + ' correos', '/ops?view=aprobaciones&filter=correos') : T('edit_mail', 'correo', 'editó 1 correo', (n) => 'editó ' + n + ' correos', '/ops?view=aprobaciones&filter=correos');
  if (tool === 'email_reject') return T('reject_mail', 'correo', 'rechazó 1 correo', (n) => 'rechazó ' + n + ' correos', '/ops?view=aprobaciones&filter=correos');
  if (tool === 'email_reopen') return T('reopen_mail', 'correo', 'devolvió 1 correo a borrador', (n) => 'devolvió ' + n + ' correos a borrador', '/ops?view=aprobaciones&filter=correos');
  if (tool === 'mail_config_set') { const a = e.after || {}; const bits = []; if (a.daily_cap != null) bits.push('tope ' + ((e.before || {}).daily_cap != null ? e.before.daily_cap + ' → ' : '') + a.daily_cap); if (a.window_start) bits.push('ventana ' + a.window_start + '–' + a.window_end); if (a.followup_days) bits.push('seguimientos +' + a.followup_days.join('/+')); return T('mailcfg:' + r.id, 'correo', 'cambió el correo: ' + (bits.join(', ') || 'configuración'), () => 'cambió la configuración del correo', '/ops?view=correo'); }
  if (tool === 'mail_outcome') return T('outcome:' + r.id, 'correo', 'marcó ' + (co || 'un prospecto') + ' como ' + (p.decision === 'perdido' ? 'perdido' : 'reunión'), () => '', '/ops?view=respuestas');
  if (tool === 'autosend_set') return T('autosend:' + r.id, 'correo', (p.decision === 'set' ? 'cambió' : 'cambió') + ' el envío automático', () => '', '/ops?view=control');
  if (tool === 'pause_set') return T('pause:' + r.id, 'sistema', p.decision === 'paused' ? 'PAUSÓ todo el sistema' + (p.reason ? ' (' + p.reason + ')' : '') : 'reanudó el sistema', () => '', '/ops?view=controles');
  if (tool === 'content_approve') return T('approve_post', 'redes', 'aprobó 1 publicación', (n) => 'aprobó ' + n + ' publicaciones', '/ops?view=contenido');
  if (tool === 'content_reject') return T('reject_post', 'redes', 'rechazó 1 publicación', (n) => 'rechazó ' + n + ' publicaciones', '/ops?view=contenido');
  if (tool === 'idea_decide') { const d = p.decision; const v = d === 'approve' ? 'aprobó' : d === 'discard' ? 'descartó' : d === 'change' ? 'pidió cambios a' : 'movió'; return T('idea_' + d, 'redes', v + ' 1 idea', (n) => v + ' ' + n + ' ideas', '/ops?view=ideas'); }
  if (tool === 'idea_mine') return T('idea_mine', 'redes', 'agregó una idea propia', (n) => 'agregó ' + n + ' ideas propias', '/ops?view=ideas');
  if (/^taller_/.test(tool)) { const v = { feedback: 'pidió cambios en', approve: 'aprobó', schedule: 'programó', discard: 'descartó', duplicate: 'duplicó', caption: 'editó el texto de', add_version: 'subió una versión de' }[tool.replace('taller_', '')] || 'actuó sobre'; return T('taller_' + tool + ':' + (e.piece_id || ''), 'redes', v + ' «' + String(co || 'una pieza').slice(0, 50) + '»', () => '', '/ops?view=taller' + (e.piece_id ? '&pieza=' + e.piece_id : '')); }
  if (/^(prep_|li_)/.test(tool)) return T('prep', 'prospeccion', 'actualizó 1 contacto preparado', (n) => 'actualizó ' + n + ' contactos preparados', '/ops?view=control');
  if (/^linkedin_/.test(tool)) return T('li', 'prospeccion', 'decidió 1 envío por LinkedIn', (n) => 'decidió ' + n + ' envíos por LinkedIn', '/ops?view=outreach&tab=linkedin');
  if (/^(list_|get_|lint_)/.test(tool)) return null; // consultas: no son acciones
  return T('tool:' + tool, 'sistema', 'usó «' + tool + '»', (n) => 'usó «' + tool + '» ' + n + ' veces', null);
}

function hiRunLabel(kind) {
  return { prospect_radar: 'el Radar de prospectos', content_radar: 'el Radar de contenido', content_rss: 'la lectura de RSS', competitor_intel: 'el informe de competencia', content_pieces: 'la creación de piezas', contact_prep: 'la preparación de contactos', story_day: 'las historias del día', ig_week: 'la semana de Instagram', ideas_week: 'la propuesta de ideas' }[kind] || kind;
}

function historyView(d) {
  const tz = d.tz || 'America/Santiago';
  const ev = [];
  const push = (at, x) => { const t = Date.parse(at); if (Number.isFinite(t) && x) ev.push({ t, ...x }); };
  for (const r of Array.isArray(d.audit) ? d.audit : []) push(r.created_at, hiAudit(r));
  for (const r of Array.isArray(d.runs) ? d.runs : []) {
    const sm = r.summary || {};
    const skip = r.status === 'skipped' || sm.mode === 'skip';
    const extra = skip ? ' (omitido' + (sm.reason ? ': ' + String(sm.reason).slice(0, 60) : '') + ')' : (sm.imported != null ? ' · ' + sm.imported + ' nuevos' : sm.created != null ? ' · ' + sm.created + ' creados' : '');
    push(r.created_at, { key: 'run:' + r.id, actor: 'Hermes', section: /prospect|contact/.test(r.kind) ? 'prospeccion' : 'redes', one: 'corrió ' + hiRunLabel(r.kind) + extra, many: () => '', href: null });
  }
  for (const m of Array.isArray(d.msgs) ? d.msgs : []) {
    const err = String(m.error || '');
    if (m.direction === 'inbound') { if (m.classification !== 'own') push(m.created_at, { key: 'in:' + (m.classification || 'x'), actor: 'Gmail', section: 'correo', one: 'recibió 1 ' + (m.classification === 'bounce' ? 'rebote' : m.classification === 'unsubscribe' ? 'baja' : m.classification === 'auto_reply' ? 'respuesta automática' : 'respuesta'), many: (n) => 'recibió ' + n + ' ' + (m.classification === 'bounce' ? 'rebotes' : m.classification === 'unsubscribe' ? 'bajas' : m.classification === 'auto_reply' ? 'respuestas automáticas' : 'respuestas'), href: '/ops?view=respuestas', who: m.company_name }); continue; }
    if (m.status === 'sent' && m.sent_at) push(m.sent_at, { key: 'sent', actor: 'Motor', section: 'correo', one: 'envió 1 correo', many: (n) => 'envió ' + n + ' correos', href: '/ops?view=respuestas', who: m.company_name });
    if (m.status === 'cancelled' && /^Cancelado por el motor/.test(err)) push(m.updated_at, { key: 'mcancel:' + err.slice(0, 60), actor: 'Motor', section: 'correo', one: 'canceló 1 correo: ' + err.replace(/^Cancelado por el motor:\s*/, ''), many: (n) => 'canceló ' + n + ' correos: ' + err.replace(/^Cancelado por el motor:\s*/, ''), href: '/ops?view=aprobaciones&filter=correos', who: m.company_name });
    if (m.status === 'draft' && /^Devuelto a borrador por el motor/.test(err)) push(m.updated_at, { key: 'mreturn', actor: 'Motor', section: 'correo', one: 'devolvió 1 correo a borrador: el texto cambió', many: (n) => 'devolvió ' + n + ' correos a borrador: el texto cambió', href: '/ops?view=aprobaciones&filter=correos', who: m.company_name });
    if (m.status === 'cancelled' && /^Reemplazado por la versión editada por Christian/.test(err)) push(m.updated_at, { key: 'replaced', actor: 'Christian', section: 'correo', one: 'reemplazó 1 borrador de Hermes por su versión', many: (n) => 'reemplazó ' + n + ' borradores de Hermes por su versión', href: '/ops?view=aprobaciones&filter=correos', who: m.company_name });
  }
  for (const p of Array.isArray(d.pieces) ? d.pieces : []) {
    if (p.is_test) continue;
    if (p.published_at) push(p.published_at, { key: 'pub', actor: 'GHL', section: 'redes', one: 'publicó «' + String(p.topic || '').slice(0, 50) + '»', many: (n) => 'publicó ' + n + ' piezas', href: '/ops?view=contenido' });
  }
  for (const a of Array.isArray(d.alerts) ? d.alerts : []) {
    if (/^_state:/.test(a.alert_key || '') || !['critical', 'high'].includes(a.severity) || (a.meta && a.meta.notice)) continue;
    push(a.first_seen_at, { key: 'alert:' + a.alert_key, actor: 'Alertas', section: 'sistema', one: (a.severity === 'critical' ? 'CRÍTICA: ' : 'importante: ') + String(a.title || '').slice(0, 120) + (a.status === 'resolved' && a.resolved_at ? ' (resuelta)' : ''), many: () => '', href: '/ops?view=sistema' });
  }
  ev.sort((a, b) => b.t - a.t);
  // Agrupar: misma clave, mismo actor, mismo día y a menos de 45 min del primero del grupo
  const dayOf = (t) => new Date(t).toLocaleDateString('en-CA', { timeZone: tz });
  const hm = (t) => new Date(t).toLocaleTimeString('es-CL', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false });
  const groups = [];
  for (const e of ev) {
    const g = groups[groups.length - 1];
    if (g && g.key === e.key && g.actor === e.actor && g.day === dayOf(e.t) && g.first - e.t <= 45 * 60000) { g.n++; g.last = e.t; if (e.who && g.who.length < 4 && !g.who.includes(e.who)) g.who.push(e.who); continue; }
    groups.push({ key: e.key, actor: e.actor, section: e.section, one: e.one, many: e.many, href: e.href, first: e.t, last: e.t, n: 1, day: dayOf(e.t), who: e.who ? [e.who] : [] });
  }
  const lines = groups.map((g) => {
    const verb = g.n > 1 && g.many(g.n) ? g.many(g.n) : g.one;
    const span = g.n > 1 && g.first - g.last >= 60000 ? hm(g.last) + '–' + hm(g.first) : hm(g.first);
    return { at: new Date(g.first).toISOString(), day: g.day, time: span, actor: g.actor, section: g.section, count: g.n, text: g.actor + ' ' + verb + ' (' + span + ')', who: g.who, href: g.href };
  });
  const uniq = (k) => [...new Set(lines.map((l) => l[k]))];
  return { generated_at: new Date(d.now).toISOString(), lines: lines.slice(0, 600), actors: uniq('actor'), sections: uniq('section'), days: uniq('day').slice(0, 90), retention_days: 90 };
}

function costsView(d) {
  const hg = d.higgs && typeof d.higgs === 'object' ? d.higgs : null;
  const pieces = (d.pieces || []).filter((p) => !p.is_test && Number(p.credits_spent) > 0).sort((a, b) => Number(b.credits_spent) - Number(a.credits_spent));
  return { higgs: hg ? { balance: hg.balance == null ? null : Number(hg.balance), spent_week: Number(hg.spent_week) || 0, cap: Number(hg.cap) || 200, reserve: Number(hg.reserve) || 300, week: hg.week || null, at: hg.at || null } : null,
    pieces: pieces.slice(0, 30).map((p) => ({ id: p.id, topic: p.topic || '—', credits: Number(p.credits_spent), status: p.taller_status || p.status || null })),
    total_pieces: pieces.reduce((a, p) => a + Number(p.credits_spent), 0), note: 'Solo cuenta lo que Atacama OS gastó (registro del guardián). Tu uso en la web de Higgsfield no entra aquí, pero sí baja el saldo.' };
}

function weekView(d) {
  const tz = d.tz || 'America/Santiago';
  const now = d.now;
  const ritual = (d.ritual && wkValidateRitual(d.ritual).ok) ? d.ritual : wkDefaultRitual();
  const names = wkTasks();
  const days = wkDays(now, tz);
  const today = new Date(now).toLocaleDateString('en-CA', { timeZone: tz });
  const monday = days[0].date, friday = days[4].date;
  const nextMonday = new Date(Date.parse(monday + 'T12:00:00Z') + 7 * 86400000).toISOString().slice(0, 10);
  const inWeek = (iso) => { if (!iso) return false; const x = new Date(Date.parse(iso)).toLocaleDateString('en-CA', { timeZone: tz }); return x >= monday && x <= days[4].date; };
  const ideasNext = (d.ideas || []).filter((i) => i.week_start === nextMonday && !i.is_test);
  const proposed = ideasNext.filter((i) => ['proposed', 'changed'].includes(i.status)).length;
  const drafts = (d.messages || []).filter((m) => m.direction === 'outbound' && m.status === 'draft').length;
  const pieces = (d.pieces || []).filter((p) => !p.is_test && p.taller_status);
  const toReview = pieces.filter((p) => p.taller_status === 'para_revisar').length;
  const closing = pieces.filter((p) => p.needs_by && inWeek(p.needs_by) && p.taller_status !== 'descartada');
  const scheduled = closing.filter((p) => ['programada', 'programada_pendiente_de_clic', 'publicada'].includes(p.taller_status)).length;
  const meetings = (d.meetings || []).filter((m) => m.meeting_start).map((m) => ({ at: m.meeting_start, day: new Date(Date.parse(m.meeting_start)).toLocaleDateString('en-CA', { timeZone: tz }), who: [m.name, m.company].filter(Boolean).join(' · ') || 'Reunión' }));
  const intelThisWeek = Boolean(d.intel_at && inWeek(d.intel_at));
  const light = closing.length === 0 ? 'sin_datos' : scheduled === closing.length ? 'verde' : scheduled >= Math.ceil(closing.length * 0.6) ? 'amarillo' : 'rojo';
  const task = (id, date) => {
    if (id === 'ideas') return { id, label: names[id] + ' (' + nextMonday + ')', done: ideasNext.length > 0 && proposed === 0, detail: ideasNext.length ? (proposed ? proposed + ' por decidir' : 'todas decididas') : 'aún no llega la propuesta', href: '/ops?view=ideas' };
    if (id === 'correos') return { id, label: names[id], done: drafts === 0, detail: drafts ? drafts + ' borradores esperando' : 'sin borradores', href: '/ops?view=aprobaciones&filter=correos' };
    if (id === 'reuniones') { const m = meetings.filter((x) => x.day === date); return { id, label: names[id], done: date < today, detail: m.length ? m.length + (m.length === 1 ? ' reunión' : ' reuniones') : 'sin reuniones agendadas', href: null, meetings: m }; }
    if (id === 'competencia') return { id, label: names[id], done: intelThisWeek, detail: intelThisWeek ? 'informe listo esta semana' : 'aún no llega el informe de esta semana', href: '/ops?view=contenido' };
    if (id === 'revisar_piezas') return { id, label: names[id], done: toReview === 0, detail: toReview ? toReview + ' para revisar' : 'nada pendiente', href: '/ops?view=taller' };
    if (id === 'cierre') return { id, label: names[id] + ' ' + scheduled + ' de ' + closing.length, done: closing.length > 0 && scheduled === closing.length, detail: light === 'verde' ? 'lista' : light === 'sin_datos' ? 'sin piezas con cierre esta semana' : (closing.length - scheduled) + ' por programar', href: '/ops?view=taller', light };
    return { id, label: id, done: false, detail: '', href: null };
  };
  const out = days.map((x) => ({ key: x.key, label: { lun: 'Lunes', mar: 'Martes', mie: 'Miércoles', jue: 'Jueves', vie: 'Viernes' }[x.key], date: x.date, today: x.date === today, tasks: (ritual[x.key] || []).map((t) => task(t, x.date)) }));
  const all = out.flatMap((x) => x.tasks);
  return { generated_at: new Date(now).toISOString(), week: monday, friday, ritual, days: out, progress: { done: all.filter((t) => t.done).length, total: all.length },
    meetings_today: meetings.filter((m) => m.day === today), close: { scheduled, total: closing.length, light } };
}

function wkDays(ms, tz) {
  const ymd = (t) => new Date(t).toLocaleDateString('en-CA', { timeZone: tz });
  const wd = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short' }).format(new Date(ms)));
  const mondayMs = ms - ((wd + 6) % 7) * 86400000;
  return ['lun', 'mar', 'mie', 'jue', 'vie'].map((k, i) => ({ key: k, date: ymd(mondayMs + i * 86400000) }));
}

function wkDefaultRitual() {
  return { lun: ['ideas', 'correos'], mar: ['reuniones'], mie: ['competencia'], jue: ['revisar_piezas'], vie: ['cierre'] };
}

function wkTasks() {
  return { ideas: 'Decidir las ideas de la semana', correos: 'Revisar los borradores de correo', reuniones: 'Reuniones del día', competencia: 'Leer el informe de competencia', revisar_piezas: 'Revisar piezas del Taller', cierre: 'Cierre: semana siguiente programada' };
}

function wkValidateRitual(r) {
  const days = ['lun', 'mar', 'mie', 'jue', 'vie'];
  const known = Object.keys(wkTasks());
  if (!r || typeof r !== 'object') return { ok: false, message: 'Ritual inválido.' };
  const out = {}, seen = new Set();
  for (const d of days) {
    const list = Array.isArray(r[d]) ? r[d] : [];
    if (list.length > 4) return { ok: false, message: 'Máximo 4 tareas por día.' };
    for (const t of list) {
      if (!known.includes(t)) return { ok: false, message: 'Tarea desconocida: ' + t };
      if (seen.has(t)) return { ok: false, message: 'La tarea «' + wkTasks()[t] + '» está en dos días.' };
      seen.add(t);
    }
    out[d] = list.slice();
  }
  return { ok: true, value: out };
}

function resultsView({ now, pieces, resources, attributions, leads, metrics, versions, feedback, days }) {
  const D = Number(days) > 0 ? Number(days) : 60, since = now - D * 86400000;
  const real = (pieces || []).filter((p) => p && !p.is_test);
  const res = Object.fromEntries((resources || []).map((r) => [r.id, r]));
  const resBySlug = Object.fromEntries((resources || []).map((r) => [r.slug, r]));
  const att = (attributions || []).filter((a) => !a.is_test);
  const web = (leads || []).filter((l) => l.source_section === 'recurso-cierre' && rsSlugOf(l.source_page));
  const lastMetric = {};
  (metrics || []).forEach((m) => { const k = m.content_piece_id, rank = { '24h': 1, '72h': 2, '7d': 3 }[m.metric_window] || 0; if (!lastMetric[k] || rank > lastMetric[k].rank) lastMetric[k] = { rank, likes: m.likes, comments: m.comments, shares: m.shares, window: m.metric_window }; });
  const at = (p) => p.published_at || p.scheduled_at || p.created_at;
  const shown = real.filter((p) => Date.parse(at(p)) >= since && (p.published_at || ['programada', 'publicada'].includes(p.taller_status) || att.some((a) => a.piece_id === p.id)));
  const piecesOut = shown.map((p) => {
    const r = p.resource_id ? res[p.resource_id] : null;
    const dm = att.filter((a) => a.piece_id === p.id);
    const w = r ? web.filter((l) => rsSlugOf(l.source_page) === r.slug && Date.parse(l.created_at) >= Date.parse(at(p))) : [];
    const mt = lastMetric[p.id] || null;
    return { id: p.id, topic: p.topic || '(sin título)', channel: p.channel || null, format: p.format || null, at: at(p), keyword: p.keyword || (p.idea && p.idea.keyword) || null,
      resource: r ? { slug: r.slug, name: r.name } : null, contacts_dm: dm.length, contacts_web: w.length, meetings: w.filter((l) => l.meeting_start).length,
      metrics: mt ? { likes: mt.likes, comments: mt.comments, shares: mt.shares, window: mt.window } : null };
  }).sort((a, b) => String(b.at).localeCompare(String(a.at)));
  const resOut = (resources || []).filter((r) => r.status === 'active' || web.some((l) => rsSlugOf(l.source_page) === r.slug)).map((r) => {
    const w = web.filter((l) => rsSlugOf(l.source_page) === r.slug && Date.parse(l.created_at) >= since);
    const pcs = real.filter((p) => p.resource_id === r.id).map((p) => p.id);
    return { slug: r.slug, name: r.name, web_leads: w.length, meetings: w.filter((l) => l.meeting_start).length, contacts_dm: att.filter((a) => a.resource_id === r.id || pcs.includes(a.piece_id)).length, pieces: pcs.length };
  }).sort((a, b) => b.web_leads + b.contacts_dm - (a.web_leads + a.contacts_dm) || a.slug.localeCompare(b.slug));
  const unknownWeb = web.filter((l) => !resBySlug[rsSlugOf(l.source_page)]).length;
  return { generated_at: new Date(now).toISOString(), days: D, pieces: piecesOut, resources: resOut, unknown_web: unknownWeb, summary: rsMondaySummary({ now, pieces: real, attributions: att, leads: web, resources }),
    iterations: rsIterations({ pieces: real, versions, feedback }).slice(0, 30),
    note: 'Atribución parcial: los comentarios y mensajes de Instagram no se leen solos. Registra cada contacto con «Registrar contacto de esta pieza». Oportunidades y ganados se ven en GHL.' };
}

function rsIterations({ pieces, versions, feedback }) {
  return (pieces || []).filter((p) => (versions || []).some((v) => v.piece_id === p.id)).map((p) => {
    const vs = (versions || []).filter((v) => v.piece_id === p.id && !v.is_test).sort((a, b) => a.version_no - b.version_no);
    const fb = (feedback || []).filter((f) => f.piece_id === p.id && !f.is_test);
    const first = vs[0] ? Date.parse(vs[0].created_at) : null, last = vs.length ? Date.parse(vs[vs.length - 1].created_at) : null;
    return { id: p.id, topic: p.topic || '(sin título)', format: p.format || null, status: p.taller_status || null, versions: vs.length, feedback: fb.length,
      credits: Math.round(vs.reduce((s, v) => s + Number(v.cost_credits || 0), 0) * 100) / 100, days: first && last ? Math.round(((last - first) / 86400000) * 10) / 10 : 0, first_try: vs.length === 1 && fb.length === 0 };
  }).sort((a, b) => b.versions - a.versions || b.feedback - a.feedback);
}

function rsMondaySummary({ now, pieces, attributions, leads, resources }) {
  const d = new Date(now), dow = (d.getUTCDay() + 6) % 7;
  const mon = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - (dow + 7) * 86400000, end = mon + 7 * 86400000;
  const inW = (t) => { const x = Date.parse(t); return x >= mon && x < end; };
  const byRes = Object.fromEntries((resources || []).map((r) => [r.id, r]));
  const lines = [];
  (pieces || []).forEach((p) => {
    const dm = (attributions || []).filter((a) => a.piece_id === p.id && inW(a.created_at)).length;
    const r = p.resource_id ? byRes[p.resource_id] : null;
    const w = r ? (leads || []).filter((l) => rsSlugOf(l.source_page) === r.slug && inW(l.created_at)) : [];
    const contacts = dm + w.length, meet = w.filter((l) => l.meeting_start).length;
    if (contacts || meet) lines.push({ piece_id: p.id, contacts, meetings: meet, text: '«' + String(p.topic || 'pieza').slice(0, 60) + '» trajo ' + contacts + (contacts === 1 ? ' contacto' : ' contactos') + (meet ? ' y ' + meet + (meet === 1 ? ' reunión' : ' reuniones') : '') + '.' });
  });
  lines.sort((a, b) => b.contacts + b.meetings * 3 - (a.contacts + a.meetings * 3));
  return { week: new Date(mon).toISOString().slice(0, 10), lines: lines.slice(0, 8), empty_text: lines.length ? null : 'La semana pasada ninguna pieza registró contactos (atribución parcial: faltan los contactos sin registrar).' };
}

function rsPieceContactInput(req) {
  const name = String(req.contact_name || '').trim(), handle = String(req.handle || '').trim().replace(/^@/, ''), kw = String(req.keyword || '').trim().toLowerCase();
  if (!/^[0-9a-f-]{36}$/i.test(String(req.piece_id || ''))) return { error: 'falta_pieza', message: 'piece_id inválido.' };
  if (name.length < 2 || name.length > 80) return { error: 'falta_nombre', message: 'Escribe el nombre (2–80 caracteres).' };
  if (handle && !/^[A-Za-z0-9._]{1,30}$/.test(handle)) return { error: 'usuario_invalido', message: 'El usuario de Instagram solo lleva letras, números, punto y guion bajo.' };
