function clip(text, n) {
  const t = String(text || '').replace(/\s+/g, ' ').trim();
  if (t.length <= n) return t;
  const cut = t.slice(0, n - 1);
  return (cut.replace(/\s+\S*$/, '') || cut) + '…';
}

function competitorGate(d) {
