  for (const m of msgs.filter((x) => x.kind === 'initial' && x.direction === 'outbound' && x.status === 'sent')) {
    const meta = m.metadata || {};
    if (/^(stopped|done)/.test(String(meta.followup_state || ''))) continue;
    const ft = meta.followup_tasks || {};
