function rfValidateNew(r) {
  const x = r && typeof r === 'object' ? r : {};
  const m = x.metadata && typeof x.metadata === 'object' ? x.metadata : {};
  const errors = [], warnings = [];
  const fmts = rfFormats();
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const fmt = String(m.format || '');
  if (!fmt) errors.push('formato_de_recurso_obligatorio_en_metadata.format:' + Object.keys(fmts).join('|'));
  else if (!fmts[fmt]) errors.push('formato_de_recurso_invalido:' + fmt.slice(0, 40));
  else if (x.type && fmts[fmt].type !== x.type) warnings.push('tipo_no_coincide_con_el_formato:' + fmt + '→' + fmts[fmt].type);
  const diff = String(m.differentiator || '').trim();
  if (diff.length < 20) errors.push('diferenciador_obligatorio_metadata.differentiator_20+_caracteres_que_hace_este_recurso_distinto_y_util');
  const text = norm(String(x.name || '') + ' ' + String(x.problem || ''));
  if (/\b(ebook|e-book|pdf gratis|guia gratis|descarga gratis|libro blanco|whitepaper)\b/.test(text)) errors.push('recurso_generico_ebook_pdf_o_guia_gratis_sin_diferenciacion');
  if (x.type === 'documento') errors.push('tipo_documento_es_un_pdf_generico_usa_un_formato_con_logica_o_estructura_propia');
  if (m.only_for_cta === true) errors.push('no_se_crean_recursos_solo_para_tener_un_cta');
  if (fmt && fmts[fmt] && fmts[fmt].interactive && String(x.status || 'draft') === 'active' && m.interactive_verified !== true) warnings.push('recurso_interactivo_activo_sin_verificar_que_funciona');
  return { errors, warnings };
}

function growthNorm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ ]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function growthResourceRank(resources, query, opts) {
  const o = opts || {};
  const stop = new Set(['de', 'la', 'el', 'los', 'las', 'un', 'una', 'para', 'por', 'con', 'que', 'en', 'y', 'o', 'a', 'del', 'al', 'mi', 'tu', 'su', 'se', 'es', 'como', 'qué', 'cómo']);
  const toks = (t) => growthNorm(t).split(' ').filter((w) => w.length > 2 && !stop.has(w));
  const q = toks(query);
  const list = (Array.isArray(resources) ? resources : []).filter((r) => r && (r.status === 'active' || (o.includeDraft && r.status === 'draft')));
  const scored = list.map((r) => {
    const name = toks(r.name), topic = toks(r.topic), problem = toks(r.problem), aud = toks(r.audience);
    let s = 0;
    q.forEach((w) => {
      if (name.some((n) => n.startsWith(w) || w.startsWith(n))) s += 3;
      if (topic.some((n) => n.startsWith(w) || w.startsWith(n))) s += 3;
      if (problem.some((n) => n.startsWith(w) || w.startsWith(n))) s += 2;
      if (aud.some((n) => n.startsWith(w) || w.startsWith(n))) s += 1;
    });
    return { ...r, match_score: s };
  }).filter((r) => (q.length ? r.match_score > 0 : true));
  scored.sort((a, b) => b.match_score - a.match_score || String(b.created_at || '').localeCompare(String(a.created_at || '')));
  return scored.slice(0, o.limit || 5);
}

function v3Age(ms, nowMs) {
  const t = Number.isFinite(ms) ? Math.max(0, nowMs - ms) : 0;
  const h = Math.floor(t / 3600000), dd = Math.floor(h / 24);
  return { text: dd >= 1 ? 'hace ' + dd + ' d' : h >= 1 ? 'hace ' + h + ' h' : 'hace minutos', tone: h < 24 ? 'fresh' : h < 72 ? 'warn' : 'old' };
}

